   (10, 5, '3', 'Por tener la suficiencia investigadora/DEA/Trabajo Tutelado de INiciación a la Investigación', 'Excluyente con 1.5.1, 1.5.2, 1.5.4, 1.5.5, 1.5.6 y 1.5.7', 'S', 'SI/NO', 3, 1, 1, 'AI', 'S', 'pmperez');
