   (16, 6, '2', 'Años de disfrute de beca de investigación no homologada por la Universidad de Jaén', 'No se consideran las becas de tecnólogos o técnicos', 'S', 'DECIMAL', 0.5, 0.1, 30, 'S', 'pmperez');
